import React, { useState } from 'react';
import { Modal, View, Text, TouchableOpacity, FlatList, Image, TextInput, StyleSheet, Share, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { BRAND } from './theme';

export function CreateMenuModal({ visible, onClose, onSelect, c }: any) {
  const items = [
      { k: 'reel', label: 'Reel', icon: 'film-outline' },
          { k: 'edits', label: 'Edits', icon: 'cut-outline' },
              { k: 'post', label: 'Post', icon: 'grid-outline' },
                  { k: 'story', label: 'Story', icon: 'add-circle-outline' },
                      { k: 'instants', label: 'Instants', icon: 'flash-outline' },
                          { k: 'highlights', label: 'Highlights', icon: 'heart-circle-outline' },
                              { k: 'live', label: 'Live', icon: 'radio-outline' },
                                  { k: 'ad', label: 'Ad', icon: 'trending-up-outline' },
                                      { k: 'channel', label: 'Channel', icon: 'chatbubbles-outline' },
                                        ];
                                          return (
                                              <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
                                                    <TouchableOpacity style={s.bg} activeOpacity={1} onPress={onClose}>
                                                            <View style={[s.sheet, { backgroundColor: c.background }]}>
                                                                      <View style={s.handle} />
                                                                                <Text style={[s.sTitle, { color: c.text }]}>Create</Text>
                                                                                          {items.map((it) => (
                                                                                                      <TouchableOpacity key={it.k} style={s.menuRow} onPress={() => { onClose(); onSelect(it.k); }}>
                                                                                                                    <Ionicons name={it.icon as any} size={22} color={c.text} />
                                                                                                                                  <Text style={{ fontSize: 16, color: c.text, marginLeft: 14 }}>{it.label}</Text>
                                                                                                                                              </TouchableOpacity>
                                                                                                                                                        ))}
                                                                                                                                                                </View>
                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                          </Modal>
                                                                                                                                                                            );
                                                                                                                                                                            }

                                                                                                                                                                            export function FollowersModal({ visible, onClose, initialTab, user, allUsers, onOpenUser, onFollowToggle, onRemoveFollower, onMessage, c }: any) {
                                                                                                                                                                              const [tab, setTab] = useState<'followers' | 'following'>(initialTab || 'followers');
                                                                                                                                                                                const [q, setQ] = useState('');
                                                                                                                                                                                  const ids: string[] = tab === 'followers' ? (user?.followers || []) : (user?.following || []);
                                                                                                                                                                                    const list = allUsers.filter((u: any) => ids.includes(u.id) && (u.username || '').toLowerCase().includes(q.toLowerCase()));
                                                                                                                                                                                      const myFollowing: string[] = user?.following || [];

                                                                                                                                                                                        return (
                                                                                                                                                                                            <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
                                                                                                                                                                                                  <View style={{ flex: 1, backgroundColor: c.background, paddingTop: 46 }}>
                                                                                                                                                                                                          <View style={s.topHdr}>
                                                                                                                                                                                                                    <TouchableOpacity onPress={onClose}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                              <Text style={{ fontSize: 18, fontWeight: '700', color: c.text }}>{user?.username || 'Profile'}</Text>
                                                                                                                                                                                                                                        <View style={{ width: 24 }} />
                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                        <View style={s.tabBar}>
                                                                                                                                                                                                                                                                  <TouchableOpacity style={[s.tabBtn, tab === 'followers' && s.tabAct]} onPress={() => setTab('followers')}>
                                                                                                                                                                                                                                                                              <Text style={{ fontWeight: '700', color: tab === 'followers' ? c.text : c.muted }}>{(user?.followers || []).length} followers</Text>
                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={[s.tabBtn, tab === 'following' && s.tabAct]} onPress={() => setTab('following')}>
                                                                                                                                                                                                                                                                                                              <Text style={{ fontWeight: '700', color: tab === 'following' ? c.text : c.muted }}>{(user?.following || []).length} following</Text>
                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                        <TextInput value={q} onChangeText={setQ} placeholder="Search" placeholderTextColor={c.muted} style={[s.inp, { backgroundColor: c.input, color: c.text }]} />
                                                                                                                                                                                                                                                                                                                                                <FlatList
                                                                                                                                                                                                                                                                                                                                                          data={list} keyExtractor={(i) => i.id}
                                                                                                                                                                                                                                                                                                                                                                    ListEmptyComponent={<Text style={{ textAlign: 'center', color: c.muted, marginTop: 40 }}>No users here yet</Text>}
                                                                                                                                                                                                                                                                                                                                                                              renderItem={({ item }) => {
                                                                                                                                                                                                                                                                                                                                                                                          const isF = myFollowing.includes(item.id);
                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={s.uRow} onPress={() => { onClose(); onOpenUser(item.id); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                    {item.photoUrl ? <Image source={{ uri: item.photoUrl }} style={s.av} /> : <View style={[s.av, s.ph]}><Ionicons name="person" size={18} color="#fff" /></View>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={{ flex: 1 }}><Text style={{ fontWeight: '700', color: c.text }}>{item.username}</Text><Text style={{ fontSize: 12, color: c.muted }}>{item.fullName || item.name || ''}</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {isF ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity style={[s.btn, { backgroundColor: c.input }]} onPress={() => { onClose(); onMessage(item); }}><Text style={{ fontWeight: '600', color: c.text }}>Message</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity style={[s.btn, { backgroundColor: '#3B82F6' }]} onPress={() => onFollowToggle(item.id)}><Text style={{ fontWeight: '600', color: '#fff' }}>Follow back</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {tab === 'followers' && <TouchableOpacity onPress={() => onRemoveFollower(item.id)} style={{ padding: 6 }}><Ionicons name="close" size={18} color={c.muted} /></TouchableOpacity>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                export function ShareQrModal({ visible, onClose, uid, username }: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const url = `flevora://user/${uid}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=260x260&data=${encodeURIComponent(url)}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={{ flex: 1, backgroundColor: '#C026D3', paddingTop: 50, paddingHorizontal: 20, justifyContent: 'space-between', paddingBottom: 36 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onPress={onClose}><Ionicons name="close" size={28} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={{ borderWidth: 1, borderColor: '#fff', borderRadius: 16, paddingHorizontal: 14, paddingVertical: 4 }}><Text style={{ color: '#fff', fontWeight: '700', fontSize: 12 }}>COLOR</Text></View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={{ width: 28 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={s.qrCard}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Image source={{ uri: qrUrl }} style={{ width: 210, height: 210 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={{ fontSize: 22, fontWeight: '800', color: BRAND, marginTop: 14 }}>@{(username || 'user').toUpperCase()}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={s.qrActions}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={s.qrBtn} onPress={() => Share.share({ message: `Follow @${username} on Flevora: ${url}` })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="share-social-outline" size={22} color="#111" /><Text style={s.qrLbl}>Share profile</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={s.qrBtn} onPress={() => Alert.alert('Profile Link', url, [{ text: 'Share', onPress: () => Share.share({ message: url }) }, { text: 'OK' }])}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="link-outline" size={22} color="#111" /><Text style={s.qrLbl}>Copy link</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={s.qrBtn} onPress={() => Share.share({ url: qrUrl, message: qrUrl })}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="download-outline" size={22} color="#111" /><Text style={s.qrLbl}>Download</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export function DraftsModal({ visible, onClose, drafts, onEdit, onAction, c }: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const [menuId, setMenuId] = useState<string | null>(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={{ flex: 1, backgroundColor: c.background, paddingTop: 46 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={s.topHdr}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={onClose}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ fontSize: 18, fontWeight: '700', color: c.text }}>Reels drafts</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={{ width: 24 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            data={drafts} keyExtractor={(i) => i.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ListEmptyComponent={<Text style={{ textAlign: 'center', color: c.muted, marginTop: 40 }}>No drafts saved yet</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={s.uRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Image source={{ uri: item.uri }} style={{ width: 58, height: 58, borderRadius: 10, backgroundColor: '#111' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={{ flex: 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ fontWeight: '700', color: c.text }}>{item.title || 'Draft'}{item.pinned ? ' 📌' : ''}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ fontSize: 12, color: c.muted }}>{item.date || 'Saved draft'}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity onPress={() => { onClose(); onEdit(item); }} style={{ padding: 8 }}><Ionicons name="pencil" size={19} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onPress={() => setMenuId(item.id)} style={{ padding: 8 }}><Ionicons name="ellipsis-horizontal" size={20} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Modal visible={!!menuId} transparent animationType="fade" onRequestClose={() => setMenuId(null)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity style={s.bg} activeOpacity={1} onPress={() => setMenuId(null)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={[s.sheet, { backgroundColor: '#1F2937' }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {['Duplicate', 'Pin', 'Rename', 'Open in Edits', 'Delete'].map((act) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity key={act} style={s.menuRow} onPress={() => { const id = menuId; setMenuId(null); onAction(id, act); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ color: act === 'Delete' ? '#EF4444' : '#fff', fontSize: 16, fontWeight: '600' }}>{act}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const s = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        bg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sheet: { borderTopLeftRadius: 20, borderTopRightRadius: 20, paddingHorizontal: 18, paddingBottom: 28, paddingTop: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            handle: { width: 38, height: 4, borderRadius: 2, backgroundColor: '#CBD5E1', alignSelf: 'center', marginBottom: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              sTitle: { fontSize: 17, fontWeight: '700', textAlign: 'center', marginBottom: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                menuRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: 13 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  topHdr: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 16, paddingBottom: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tabBar: { flexDirection: 'row', borderBottomWidth: 0.5, borderColor: '#E5E7EB' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      tabBtn: { flex: 1, alignItems: 'center', paddingVertical: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tabAct: { borderBottomWidth: 2, borderColor: '#111827' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          inp: { margin: 14, borderRadius: 12, paddingHorizontal: 14, paddingVertical: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            uRow: { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 10, gap: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              av: { width: 46, height: 46, borderRadius: 23 }, ph: { backgroundColor: BRAND, alignItems: 'center', justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btn: { paddingHorizontal: 14, paddingVertical: 7, borderRadius: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  qrCard: { backgroundColor: '#fff', borderRadius: 24, padding: 28, alignItems: 'center', elevation: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    qrActions: { backgroundColor: '#fff', borderRadius: 20, flexDirection: 'row', justifyContent: 'space-around', paddingVertical: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      qrBtn: { alignItems: 'center', gap: 6 }, qrLbl: { fontSize: 12, fontWeight: '600', color: '#111' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      